import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {H1} from '@jetbrains/ring-ui-built/components/heading/heading'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import cn from 'classnames'
import {Suspense} from 'react'
import type {PreloadedQuery} from 'react-relay'

import type {DialogProps} from '../../../../../hocs/withDialogContainer'
import withDialogContainer from '../../../../../hocs/withDialogContainer'
import {DialogType} from '../../../../../types'
import Loader from '../../../../common/Loader/Loader'
import type {AgentsPagesAgentTypesQuery} from '../../__generated__/AgentsPagesAgentTypesQuery.graphql'

import AgentPoolsFavoriteListContainer from './AgentPoolsFavoriteList/AgentPoolsFavoriteList.container'

import styles from './AgentPoolsFavoriteDialog.module.css'

export interface Props {
  id: string
  searchQuery?: string
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
}

function AgentPoolsFavoriteDialogContent(props: {
  searchQuery?: string
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
}) {
  const {searchQuery, agentTypesQueryRef} = props
  return (
    <div className={cn(styles.content, styles.scrollableWrapper)}>
      <div>
        <H1 className={styles.header}>{'Configure Favorites Agent Pools'}</H1>
        <div className={styles.shortcuts}>
          {'Toggle favorites: Enter'}
          <br />
          {'Move: ↑↓'}
        </div>
      </div>
      <Suspense fallback={<Loader />}>
        <AgentPoolsFavoriteListContainer
          searchQuery={searchQuery}
          agentTypesQueryRef={agentTypesQueryRef}
        />
        <Panel className={styles.footer}>{'Changes are applied automatically'}</Panel>
      </Suspense>
    </div>
  )
}

export function AgentPoolsFavoriteDialogComponent({
  isOpened,
  closeDialog,
  searchQuery,
  agentTypesQueryRef,
}: DialogProps<Props>) {
  return (
    <Dialog
      label="Configure Favorites Agent Pools"
      show={isOpened}
      onCloseAttempt={closeDialog}
      contentClassName={styles.dialog}
      showCloseButton
      closeButtonInside
    >
      <AgentPoolsFavoriteDialogContent
        searchQuery={searchQuery}
        agentTypesQueryRef={agentTypesQueryRef}
      />
    </Dialog>
  )
}

export const AgentPoolsFavoriteDialog = withDialogContainer<Props>(
  DialogType.FAVORITE_AGENT_POOLS,
  (_, props) => props.id,
)(AgentPoolsFavoriteDialogComponent)
